(()=>{
 'use strict';
 const E=window.OrderPromise,$=s=>document.querySelector(s);
 let state=E.seed(),view='overview',selected='A101',filter='All',report=null,toastTimer;
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n),time=s=>new Date(s).toISOString().slice(11,16)+' UTC',cls=s=>s==='At risk'?'risk':s.toLowerCase();
 function toast(s){$('#toast').textContent=s;$('#toast').className='visible';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').className='',6500);}
 function heading(k,title,sub,action=''){return`<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;}
 function stats(){const fs=E.findings(state),risks=fs.filter(f=>f.status==='At risk');return`<div class="stats"><div class="stat"><div class="stat-label">INTEGRATION CALLS</div><div class="stat-value teal">${state.events.length}/${state.events.length}</div><div class="stat-note">Recorded calls report success</div></div><div class="stat"><div class="stat-label">ORDERS AT RISK</div><div class="stat-value red">${risks.length}<span style="font-size:13px;color:#798c7c"> / ${state.orders.length}</span></div><div class="stat-note">${fs.filter(f=>f.status==='Unknown').length} unknown · ${fs.filter(f=>f.status==='Pending').length} within deadline</div></div><div class="stat"><div class="stat-label">FLAGGED ORDER VALUE</div><div class="stat-value">${money(risks.reduce((n,f)=>n+state.orders.find(o=>o.id===f.orderId).value,0))}</div><div class="stat-note">Synthetic value; not measured loss</div></div><div class="stat"><div class="stat-label">SANDBOX RECOVERIES</div><div class="stat-value teal">${state.recoveries.length}</div><div class="stat-note">Human approved · evidence verified</div></div></div>`;}
 function details(){const o=state.orders.find(o=>o.id===selected),f=E.inspect(state,o),ex=E.explain(state,o),evs=state.events.filter(e=>e.orderId===o.id).slice().sort((a,b)=>a.at.localeCompare(b.at)),recovered=state.recoveries.some(r=>r.orderId===o.id);return`<div class="card"><div class="card-head"><div><h2>Investigate the outcome</h2><small>Follow the promise, not just the API status.</small></div><span class="eyebrow">${esc(o.id)}</span></div><div class="detail"><div class="detail-title"><div><h2>${esc(o.customer)}</h2><p>${esc(o.id)} · ${money(o.value)} · Ship by ${time(o.due)}</p></div><span class="badge ${cls(f.status)}">${f.status}</span></div><div class="divider"></div><div class="section-label">Expected order journey</div><div class="journey">${['accepted','reserved','shipped','invoiced'].map((type,i)=>{const done=evs.some(e=>e.type===type);return`<div class="stage ${done?'done':type==='shipped'&&f.late?'missing':''}"><i>${done?'✓':i+1}</i>${type[0].toUpperCase()+type.slice(1)}</div>`;}).join('')}</div><div class="finding ${f.status==='Healthy'?'good':''}"><h3>${esc(f.title)}</h3><p>${esc(f.rule)}. ${esc(f.next)}</p></div><div class="section-label">Source evidence · ${evs.length} events</div><ol class="evidence">${evs.map(e=>`<li><time>${time(e.at)}</time><strong>${esc(e.source)} · ${esc(e.type)}</strong><code>${esc(e.id)}<br>ref: ${esc(e.ref)} · call: Succeeded</code></li>`).join('')}</ol><div class="explanation"><div class="mode">✧ EXPLANATION PREVIEW · DETERMINISTIC, NO LIVE AI</div><p>${esc(ex.summary)}</p><p>Feed observed through <b>${time(state.feedThrough)}</b>. Checked at <b>${time(state.now)}</b>.</p><small>${esc(ex.limitation)}</small></div>${f.recoverable?`<label class="approval"><input type="checkbox" id="approval">I reviewed the reservation and approve one simulated shipment for ${esc(o.id)}.</label><div class="recovery-actions"><button class="primary" id="recover" disabled>Approve sandbox recovery ↗</button></div>`:recovered?`<div class="notice">Shipment outcome verified. The sandbox recovery created one shipment.</div><div class="recovery-actions"><button id="replay">Replay recovery request</button></div>`:`<div class="note">${f.status==='At risk'?'Human investigation required. This case has no automatic recovery.':'No recovery action is permitted for the current evidence.'}</div>`}<div class="status-message" id="recovery-message" aria-live="polite"></div></div></div>`;}
 function overview(){const fs=E.findings(state),shown=fs.filter(f=>filter==='All'||f.status===filter);return heading('Customer outcome assurance','Track the promise. Find the delay. Resolve the issue.','See the customer orders hidden behind technically successful integrations. Investigate evidence and recover with intent.','<button class="primary" id="run-checks">↻ Run outcome checks</button>')+`<div class="banner"><span class="banner-icon">◈</span><div><strong>Technical success is only half the story.</strong><p>All recorded calls succeeded. Outcome rules check deadlines, shipment uniqueness, billing consistency, and feed freshness.</p></div><span class="pill">Evidence first</span></div>`+stats()+`<div class="content-grid"><div class="card"><div class="card-head"><div><h2>Order watchlist</h2><small>Six synthetic journeys · four outcome rules</small></div><span class="pill">${time(state.now)}</span></div><div class="filters">${['All','At risk','Healthy','Pending','Unknown'].map(s=>`<button class="chip ${s===filter?'selected':''}" data-filter="${s}">${s}</button>`).join('')}</div><div class="order-list">${shown.map(f=>{const o=state.orders.find(o=>o.id===f.orderId);return`<button class="order-row ${selected===o.id?'selected':''}" data-order="${o.id}" aria-label="Inspect ${o.id}: ${esc(o.customer)}"><span class="order-symbol ${cls(f.status)}">${f.status==='Healthy'?'✓':f.status==='Pending'?'◷':f.status==='Unknown'?'?':'!'}</span><span class="order-name"><strong>${o.id} <span style="font-weight:400;color:#64796b">· ${esc(o.customer)}</span></strong><p>${f.title}</p></span><span class="order-end"><span class="badge ${cls(f.status)}">${f.severity}</span><small>${money(o.value)} ↗</small></span></button>`;}).join('')||'<div class="empty">No orders match this filter.</div>'}</div></div>${details()}</div><div class="clockbar"><span>● Shipping feed: <b>${Date.parse(state.now)-Date.parse(state.feedThrough)>900000?'stale':'fresh'}</b> · watermark ${time(state.feedThrough)}</span><span>Session memory only · refresh restores original scenario</span></div>`;}
 const sample={id:'manual-A101-shipment',orderId:'A101',type:'shipped',at:'2026-10-25T11:55:00Z',ref:'SHP-MANUAL-A101',source:'Shipping'};
 function lab(){return heading('Controlled experiments','Make the edge cases visible.','Inject an event, interrupt evidence, or advance time. Every control affects this browser session only.')+`<div class="lab-grid"><div class="card panel"><h2>Event injection</h2><p class="subtitle">Resolve A101 using a late-arriving source event. Repeat the event to test deduplication.</p><div class="controls"><button id="sample-event">Load sample</button></div><label class="field" for="event-json">One synthetic event (JSON)</label><textarea id="event-json" spellcheck="false">${esc(JSON.stringify(sample,null,2))}</textarea><div class="controls"><button class="primary" id="inject">Validate & ingest event</button></div><div id="event-message" class="status-message" role="status"></div><p class="note">Known orders only; accepted, reserved, shipped or invoiced. UTC timestamps must not be in the future. Repeated shipment references count once. Unknown properties are discarded.</p></div><div><div class="card panel"><h2>Simulation controls</h2><div class="controls"><button id="stale">Simulate stale feed</button><button id="fresh">Refresh feed watermark</button><button id="advance">Advance clock +2 hours</button></div><p class="note">Feed freshness window: 15 minutes. A stale watermark suppresses missing-event conclusions. Advancing time does not refresh the feed.</p><div class="notice">Clock: ${esc(state.now)}<br>Watermark: ${esc(state.feedThrough)}</div><button id="reset">Reset demo scenario</button></div><div class="card panel" style="margin-top:20px"><h2>Session audit trail</h2><p class="note">Prototype history; no persistent or tamper-proof audit store.</p><div class="audit">${state.audit.slice().reverse().map(a=>`<div class="audit-item">${time(a.at)} · ${esc(a.action)}<br>${esc(a.orderId||'SYSTEM')} / ${esc(a.detail)}</div>`).join('')||'<div class="empty">No actions recorded yet.</div>'}</div></div></div></div>`;}
 function evaluation(){return heading('Measured, reproducible checks','Prove the behavior.','Run a fixed synthetic suite independently of your current session. Expected results are explicit.','<button class="primary" id="evaluate">Run regression suite</button>')+`<div class="banner"><span class="banner-icon">✓</span><div><strong>${report?`${report.passed} / ${report.total} checks passed`:'Evaluation ready'}</strong><p>Normal journeys, deadlines, duplicate references, stale feeds, late events, approval, and recovery replay.</p></div></div><div class="card table-scroll">${report?`<table><thead><tr><th>SCENARIO</th><th>EXPECTED</th><th>ACTUAL</th><th>RESULT</th></tr></thead><tbody>${report.cases.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.expected)}</td><td>${esc(c.actual)}</td><td class="${c.passed?'pass':'fail'}">${c.passed?'PASS':'FAIL'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Run the suite to generate an evidence-backed result.</div>'}</div><p class="note">Hand-authored synthetic cases, not a statistically representative accuracy benchmark. Production time savings, revenue benefit, and live AI quality have not been measured. Export evidence to download the current scenario and test report.</p>`;}
 function architecture(){return heading('Build transparency','Small scope. Clear boundaries.','Business outcome checks, evidence-grounded explanations, and human-approved sandbox recovery.')+`<div class="card panel"><div class="eyebrow">Implemented locally</div><div class="flow"><div><span>01 / INPUT</span><b>Synthetic event stream</b><p>Sales, inventory, shipping, billing. Correlated by order ID.</p></div><div><span>02 / VERIFY</span><b>Outcome rule engine</b><p>Deadline, duplicates, invoice consistency, freshness checks.</p></div><div><span>03 / REVIEW</span><b>Evidence workbench</b><p>Source references, rule IDs, deterministic explanation preview.</p></div><div><span>04 / RECOVER</span><b>Sandbox fulfillment</b><p>Human approval, state recheck, repeat request suppression.</p></div></div><div class="prose"><h3>The customer problem</h3><p>Individual integration calls can succeed while the order journey remains incomplete or contradictory. Operators need to identify affected orders, inspect cross-system evidence, and choose a recovery without creating duplicates.</p><h3>What is working</h3><ul><li>Six synthetic orders and event injection with validation and deduplication.</li><li>Four explicit outcome rules, feed freshness handling, and time simulation.</li><li>Source evidence timelines and deterministic explanations generated from session state.</li><li>One human-approved shipment recovery and an inspectable session audit trail.</li><li>Runnable regression tests and downloadable JSON evidence.</li></ul><h3>What is simulated</h3><p>All source systems, customers, amounts, events, integration statuses and shipment execution. No database, Oracle service, cloud account, live model, external API, or physical shipment is connected. Page memory resets on reload. The optional Node server only serves static assets.</p><h3>Oracle and Java implementation path</h3><p>Future implementation: OIC adapters emit correlated events; a Java Spring Boot service validates and checks journeys; Oracle Database persists events and recovery keys; an approved AI service explains findings from cited evidence. These integrations are proposals, not delivered capabilities.</p><h3>Limits that matter</h3><p>One shipment per order is assumed. Split shipments, cancellations, returns and partial fulfillment need richer rules. A single feed watermark is a simplification. Production recovery requires transactional state, source-side idempotency, authorization and reconciliation of uncertain external outcomes. Shipment outcome met does not imply on-time physical delivery.</p><h3>Submission readiness</h3><p>Source, setup instructions, demo script, architecture, evaluation and submission draft are included. Required Oracle or live-AI usage must be checked against the event rubric.</p></div></div>`;}
 function business(){return heading('Rubric evidence','A specific operator. A testable business case.','For order-operations teams reconciling outcomes across an ERP, an external warehouse, and a separate billing system.')+`<div class="card panel"><div class="prose"><h3>First user and buyer</h3><p>The first user is an order-operations analyst at a distributor using multiple fulfillment applications. The proposed buyer is its head of order operations, with an integration lead as technical evaluator. Our initial segment is mixed-system workflows where no single console has all outcome evidence. This is a target hypothesis; no customer has committed to pay.</p><h3>Before → after</h3><p><b>Before:</b> open integration logs, find the order ID, compare shipment and invoice records, contact the owner, then decide whether to retry. <b>After:</b> select a flagged order, inspect its source references and freshness, approve one permitted sandbox action, and verify the new shipment record. The benefit hypothesis is less reconciliation effort and fewer unsafe replays.</p><h3>Evidence beyond this demo</h3><p>Oracle documents an Order Manager role, fulfillment exceptions and guided recovery. That supports the existence of the operational task; it does not quantify its prevalence or validate demand for our product. No firsthand interviews or measured investigation-time savings are claimed.</p><ul><li><a target="_blank" rel="noopener noreferrer" href="https://docs.oracle.com/en/cloud/saas/supply-chain-and-manufacturing/26a/fauom/monitor-order-fulfillment.html">Oracle: Monitor Order Fulfillment</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://docs.oracle.com/en/cloud/saas/supply-chain-and-manufacturing/26b/farom/Order_Manager_job_roles.html">Oracle: Order Manager role</a></li><li><a target="_blank" rel="noopener noreferrer" href="https://docs.oracle.com/en/cloud/saas/readiness/scm/26c/order26c/26C-order-mgmt-wn-f49710.htm">Oracle: Order Exception Assistant capabilities</a></li></ul><h3>Why another product?</h3><p>Existing Oracle functionality already monitors fulfillment and supports exception recovery. OrderPromise's proposed wedge is a small evidence workbench across mixed systems, explicit Unknown states for stale data, and reproducible recovery replay tests. This prototype does not prove superiority over Oracle or establish a moat. We should stop pursuing a standalone product if existing tools solve the target customer's workflow adequately.</p><h3>Market scope: estimate from the workflow</h3><p>Candidate users include order analysts, support teams and integration operators in distributors with external warehouses. Count qualified organizations and analysts through interviews and partner discovery; do not treat every Oracle customer as an addressable buyer. No TAM figure or customer count is asserted.</p><h3>What the next investment must prove</h3><ol><li><b>Discovery:</b> interview 5 analysts and 2 managers; observe anonymized investigations and identify whether the evidence gap remains after using existing tools.</li><li><b>Read-only pilot:</b> connect one approved event source and replay labeled normal/failure cases. Measure false alerts, missed exceptions, freshness and analyst investigation time against today's process.</li><li><b>Go/no-go:</b> proposed targets are at least 30% lower median investigation time, at least 90% alert precision on an independently labeled pilot set, and no duplicate actions in controlled recovery tests. These are targets, not achieved results.</li></ol><p>Potential defensibility would come from reliable adapters, versioned customer-specific outcome rules and permissioned, validated recovery examples. None is established at prototype stage. Pricing and willingness to pay remain untested.</p><h3>Judge verification</h3><p>No login is required. Follow the three-minute demo: review A101, approve recovery, replay it, inspect A102/A103, then test a stale feed and run Evaluation. The code and reproduction instructions are included in the downloadable source bundle.</p><p><a class="source-link" href="source-bundle.json" download>↓ Download source and verification instructions (JSON)</a></p></div></div>`;}
 function render(){const names={overview:'Outcome overview',lab:'Scenario lab',evaluation:'Evaluation',business:'Customer & business case',architecture:'Build & architecture'};$('#breadcrumb').textContent=names[view];document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});$('#main').innerHTML=({overview,lab,evaluation,business,architecture}[view])();bind();}
 function download(){const payload={application:'OrderPromise',version:'1.0.0',exportedAt:new Date().toISOString(),disclosure:'Synthetic local prototype; no database, live AI or external recovery. Not an official hackathon submission schema.',state,findings:E.findings(state),evaluation:report||E.evaluate()};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='orderpromise-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Evidence report exported.');}
 function bind(){document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{selected=b.dataset.order;render();});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});if($('#run-checks'))$('#run-checks').onclick=()=>{state.audit.push({at:state.now,action:'CHECKS_RUN',detail:`${E.findings(state).filter(f=>f.status==='At risk').length} orders at risk`});render();toast('Outcome checks complete.');};if($('#approval'))$('#approval').onchange=e=>$('#recover').disabled=!e.target.checked;
 const perform=()=>{try{const r=E.recover(state,selected,true);render();$('#recovery-message').textContent=r.message;toast(r.message);}catch(e){toast(e.message);}};if($('#recover'))$('#recover').onclick=perform;if($('#replay'))$('#replay').onclick=perform;
 if($('#inject'))$('#inject').onclick=()=>{try{const r=E.addEvent(state,JSON.parse($('#event-json').value));$('#event-message').textContent=r.message;toast(r.message);refreshAudit();}catch(e){$('#event-message').textContent=e.message;toast(e.message);}};if($('#sample-event'))$('#sample-event').onclick=()=>$('#event-json').value=JSON.stringify(sample,null,2);
 for(const[id,fn]of[['stale',()=>state.feedThrough=new Date(Date.parse(state.now)-3600000).toISOString()],['fresh',()=>state.feedThrough=state.now],['advance',()=>state.now=new Date(Date.parse(state.now)+7200000).toISOString()]])if($('#'+id))$('#'+id).onclick=()=>{fn();state.audit.push({at:state.now,action:'SIMULATION_'+id.toUpperCase(),detail:'Local simulation control'});render();toast('Scenario updated. Open Outcome overview to inspect changes.');};
 if($('#reset'))$('#reset').onclick=()=>{state=E.seed();selected='A101';filter='All';render();toast('Original scenario restored.');};if($('#evaluate'))$('#evaluate').onclick=()=>{report=E.evaluate();render();toast(`${report.passed}/${report.total} regression checks passed.`);};}
 function refreshAudit(){if($('.audit'))$('.audit').innerHTML=state.audit.slice().reverse().map(a=>`<div class="audit-item">${time(a.at)} · ${esc(a.action)}<br>${esc(a.orderId||'SYSTEM')} / ${esc(a.detail)}</div>`).join('');}
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();window.scrollTo(0,0);});$('.brand').onclick=e=>{e.preventDefault();view='overview';render();};$('#export').onclick=download;render();
})();
